def R(c,s,needle,reading,alternative,evidence,weight,key,confidence='high'):
    p=pages[c,s]; hits=[i for i in range(p['start'],p['end']+1) if needle in lines[i-1]]
    if not hits:
        missing.append((c,s,needle))
        return
    rows.append(dict(cote=c,scan=f'{s:03d}',line=';'.join(map(str,hits)),reading=reading,alternative=alternative,evidence=evidence,weight=weight,confidence=confidence,item_id=groups[key],status='unresolved; no scans supplied; current transcription unchanged'))
